const trigger = $('Trigger Telegram').item.json;
const chatId = trigger.message.chat.id;
const text = (trigger.message.text || '').trim();

let companies = $('Buscar empresas del chat').item.json.companies;
if (typeof companies === 'string') { try { companies = JSON.parse(companies); } catch (e) { companies = []; } }
if (!Array.isArray(companies)) companies = [];

const conv = $('Obtener conversacion').item.json;
const conversationId = conv.id;
let state = conv.context_state_json;
if (typeof state === 'string') { try { state = JSON.parse(state); } catch (e) { state = {}; } }
if (!state || typeof state !== 'object') state = {};
let activeFlow = conv.active_flow;

const MENU = [
  '1) Marketing automatico',
  '2) Crear publicacion manual',
  '3) Revisar publicaciones',
  '4) Revisar clientes/leads',
  '5) Ver resultados',
  '6) Crear promocion',
  '7) Otra cosa',
];

const TIPOS = ['promocion', 'producto', 'servicio', 'educativo', 'testimonial', 'marca', 'informativo', 'engagement', 'dejar_decidir'];
const TIPOS_LABEL = [
  '1) Promocion', '2) Producto', '3) Servicio', '4) Educativo', '5) Testimonial',
  '6) Marca', '7) Informativo', '8) Engagement', '9) Dejame decidir',
];

function menuText(companyName) {
  return `Buenos dias.\n\nEstas trabajando con: ${companyName}.\n\nQue deseas hacer hoy?\n\n${MENU.join('\n')}\n\n(Responde con el numero o describelo con tus palabras. Escribe "cambiar empresa" para elegir otra.)`;
}
function askCompany(list) {
  return `Con cual empresa quieres trabajar?\n\n${list.map((c, i) => `${i + 1}) ${c.name}`).join('\n')}`;
}
function askCantidad() {
  return 'Cuantas publicaciones deseas hacer hoy? (maximo 5)';
}
function askRedes() {
  return 'Donde deseas publicar?\n\n1) Facebook\n2) Instagram\n3) WhatsApp\n4) Todas';
}
function askTipo() {
  return `Que tipo de contenido quieres?\n\n${TIPOS_LABEL.join('\n')}`;
}
function askIdioma() {
  return 'En que idioma quieres la publicacion?\n\n1) Espanol\n2) Ingles';
}

function buildGeminiPrompt(brain, automatico) {
  let services = brain.services;
  let promotions = brain.promotions;
  let rules = brain.rules;
  if (typeof services === 'string') { try { services = JSON.parse(services); } catch (e) { services = []; } }
  if (typeof promotions === 'string') { try { promotions = JSON.parse(promotions); } catch (e) { promotions = []; } }
  if (typeof rules === 'string') { try { rules = JSON.parse(rules); } catch (e) { rules = []; } }
  if (!Array.isArray(services)) services = [];
  if (!Array.isArray(promotions)) promotions = [];
  if (!Array.isArray(rules)) rules = [];

  const idiomaNombre = automatico.idioma === 'en' ? 'ingles (English)' : 'espanol';

  return `Eres el redactor de marketing de la empresa "${brain.company_name}".
Sector: ${brain.sector || 'no especificado'}.
Descripcion: ${brain.description || 'no especificada'}.
Tono de comunicacion: ${brain.tone || 'profesional y cercano'}.
Colores de marca: ${brain.colors_primary || ''} y ${brain.colors_secondary || ''}.
Estilo visual: ${brain.visual_style || 'no especificado'}.

Servicios/productos reales disponibles (NUNCA inventes otros ni cambies precios):
${JSON.stringify(services)}

Promociones activas reales (si esta vacio, no hay promociones activas, no inventes ninguna):
${JSON.stringify(promotions)}

Reglas obligatorias:
${rules.join('\n')}

Tarea: genera exactamente ${automatico.cantidad} publicaciones de tipo "${automatico.tipo}" para la(s) red(es) "${automatico.redes}".
IMPORTANTE: escribe TODO el contenido (headline, caption, cta, hashtags, alt_text) completamente en ${idiomaNombre}, sin mezclar idiomas.
Responde SOLO con un arreglo JSON valido (sin texto adicional, sin markdown, sin bloque de codigo) de ${automatico.cantidad} objetos, cada uno con estas claves exactas: concept (string corto, en ${idiomaNombre}), headline (string, en ${idiomaNombre}), caption (string, el texto completo del post, en ${idiomaNombre}), cta (string corto, en ${idiomaNombre}), hashtags (arreglo de strings sin el simbolo #, en ${idiomaNombre} cuando aplique), alt_text (string describiendo la imagen para accesibilidad, en ${idiomaNombre}), image_prompt (string SIEMPRE en ingles, describiendo SOLO la escena o fondo fotografico para un generador de imagenes, sin pedir que dibuje ningun logo ni texto), platform (una de: facebook, instagram, whatsapp).
Si no hay suficiente informacion real de servicios o promociones para el tipo pedido, usa contenido informativo o de marca en su lugar, pero nunca inventes precios ni promociones que no esten en las listas de arriba.`;
}

let reply;
let newState = state;
let newFlow = activeFlow;
let action = 'reply_only';
let geminiPrompt = null;
let automatico = null;

if (companies.length === 0) {
  reply = `Hola. Tu chat de Telegram (chat_id: ${chatId}) todavia no esta vinculado a ninguna empresa. Pidele a Rafael que lo conecte.`;
} else if (/^cambiar\s+empresa/i.test(text)) {
  if (companies.length === 1) {
    newState = { company_id: companies[0].id };
    newFlow = null;
    reply = `Solo tienes una empresa conectada a este chat: ${companies[0].name}. Sigo trabajando con ella.\n\n${menuText(companies[0].name)}`;
  } else {
    newState = {};
    newFlow = 'select_company';
    reply = askCompany(companies);
  }
} else if (activeFlow === 'select_company' || (!state.company_id && companies.length > 1)) {
  let picked = null;
  const numMatch = text.match(/^(\d+)/);
  if (numMatch) {
    const idx = parseInt(numMatch[1], 10) - 1;
    if (companies[idx]) picked = companies[idx];
  }
  if (!picked) {
    const lower = text.toLowerCase();
    picked = companies.find((c) => lower.includes(c.name.toLowerCase()) || c.name.toLowerCase().includes(lower));
  }
  if (picked) {
    newState = { company_id: picked.id };
    newFlow = null;
    reply = menuText(picked.name);
  } else {
    newFlow = 'select_company';
    reply = `No reconoci esa opcion. ${askCompany(companies)}`;
  }
} else if (!state.company_id && companies.length === 1) {
  newState = { company_id: companies[0].id };
  newFlow = null;
  reply = menuText(companies[0].name);
} else {
  const company = companies.find((c) => c.id === state.company_id) || companies[0];

  if (activeFlow === 'auto_cantidad') {
    const n = parseInt(text, 10);
    if (!isNaN(n) && n >= 1 && n <= 5) {
      newState = { ...state, automatico: { cantidad: n } };
      newFlow = 'auto_redes';
      reply = askRedes();
    } else {
      newFlow = 'auto_cantidad';
      reply = `Escribe un numero entre 1 y 5. ${askCantidad()}`;
    }
  } else if (activeFlow === 'auto_redes') {
    const map = { '1': 'facebook', '2': 'instagram', '3': 'whatsapp', '4': 'todas' };
    const numMatch = text.match(/^(\d+)/);
    let redes = numMatch ? map[numMatch[1]] : null;
    if (!redes) {
      const lower = text.toLowerCase();
      if (lower.includes('todas')) redes = 'todas';
      else if (lower.includes('facebook')) redes = 'facebook';
      else if (lower.includes('instagram')) redes = 'instagram';
      else if (lower.includes('whatsapp')) redes = 'whatsapp';
    }
    if (redes) {
      const prevAuto = state.automatico || {};
      newState = { ...state, automatico: { ...prevAuto, redes } };
      newFlow = 'auto_tipo';
      reply = askTipo();
    } else {
      newFlow = 'auto_redes';
      reply = `No reconoci esa red. ${askRedes()}`;
    }
  } else if (activeFlow === 'auto_tipo') {
    const numMatch = text.match(/^(\d+)/);
    let tipo = null;
    if (numMatch) {
      const idx = parseInt(numMatch[1], 10) - 1;
      tipo = TIPOS[idx];
    }
    if (!tipo) {
      const lower = text.toLowerCase();
      if (lower.includes('decidir')) tipo = 'dejar_decidir';
      else tipo = TIPOS.find((t) => lower.includes(t));
    }
    if (tipo) {
      const prevAuto = state.automatico || {};
      newState = { ...state, automatico: { ...prevAuto, tipo } };
      newFlow = 'auto_idioma';
      reply = askIdioma();
    } else {
      newFlow = 'auto_tipo';
      reply = `No reconoci esa opcion. ${askTipo()}`;
    }
  } else if (activeFlow === 'auto_idioma') {
    const numMatch = text.match(/^(\d+)/);
    let idioma = null;
    if (numMatch) {
      if (numMatch[1] === '1') idioma = 'es';
      else if (numMatch[1] === '2') idioma = 'en';
    }
    if (!idioma) {
      const lower = text.toLowerCase();
      if (lower.includes('espan') || lower.includes('spanish')) idioma = 'es';
      else if (lower.includes('ingl') || lower.includes('english')) idioma = 'en';
    }
    if (idioma) {
      const prevAuto = state.automatico || {};
      automatico = { ...prevAuto, idioma };
      newState = { ...state, automatico };
      newFlow = null;
      action = 'generate_content';
      reply = `Generando ${automatico.cantidad} publicaciones para ${company.name} en ${idioma === 'en' ? 'ingles' : 'espanol'}, dame un momento...`;

      const brain = $('Cargar Company Brain').item.json;
      geminiPrompt = buildGeminiPrompt(brain, automatico);
    } else {
      newFlow = 'auto_idioma';
      reply = `No reconoci esa opcion. ${askIdioma()}`;
    }
  } else if (/^1\b/.test(text) || /automatico/i.test(text)) {
    newFlow = 'auto_cantidad';
    reply = askCantidad();
  } else if (/^2\b/.test(text) || /publicaci.n\s+manual/i.test(text)) {
    reply = `La creacion manual (opcion 2) se construye en el siguiente incremento de esta fase.\n\n${menuText(company.name)}`;
  } else {
    reply = `Elegiste: "${text}" para ${company.name}.\n\n(Esta opcion del menu se construye en un proximo incremento de la Fase 4.)\n\n${menuText(company.name)}`;
  }
}

return [{
  json: {
    chat_id: chatId,
    reply_text: reply,
    conversation_id: conversationId,
    new_state: JSON.stringify(newState),
    new_flow: newFlow,
    action,
    company_id: (newState && newState.company_id) || null,
    content_type: automatico ? automatico.tipo : null,
    gemini_prompt: geminiPrompt,
  },
}];

const decision = $('Decidir respuesta').item.json;
let state = {};
try { state = JSON.parse(decision.new_state); } catch (e) { state = {}; }
const cleanState = { company_id: state.company_id || decision.company_id || null };

return [{
  json: {
    chat_id: decision.chat_id,
    reply_text: 'Hubo un problema generando el contenido: el proveedor de IA esta ocupado en este momento (error temporal). Intenta de nuevo en un minuto escribiendo "1".',
    conversation_id: decision.conversation_id,
    new_state: JSON.stringify(cleanState),
    new_flow: null,
  },
}];

const decision = $('Decidir respuesta').item.json;
const geminiResponse = $input.first().json;

let draftsRaw = [];
let usage = {};
let parseError = null;
try {
  const text = geminiResponse.candidates[0].content.parts[0].text;
  draftsRaw = JSON.parse(text);
  if (!Array.isArray(draftsRaw)) draftsRaw = [draftsRaw];
} catch (e) {
  parseError = String(e);
  draftsRaw = [];
}
usage = geminiResponse.usageMetadata || {};

const drafts = draftsRaw.map((d) => ({
  concept: d.concept || '',
  headline: d.headline || '',
  caption: d.caption || '',
  cta: d.cta || '',
  hashtags: Array.isArray(d.hashtags) ? d.hashtags : [],
  alt_text: d.alt_text || '',
  image_prompt: d.image_prompt || '',
  platform: d.platform || (decision.content_type || null),
}));

let replyText;
if (drafts.length === 0) {
  replyText = `Hubo un problema generando el contenido con la IA (${parseError || 'respuesta vacia'}). Intenta de nuevo escribiendo "1".`;
} else {
  const lines = drafts.map((d, i) => {
    const hashtagsText = d.hashtags.map((h) => '#' + h).join(' ');
    return `--- Publicacion ${i + 1} (${d.platform}) ---\n${d.headline}\n\n${d.caption}\n\nCTA: ${d.cta}\nHashtags: ${hashtagsText}`;
  });
  replyText = `Aqui tienes ${drafts.length} publicacion(es) generadas para revisar:\n\n${lines.join('\n\n')}\n\n(La aprobacion y edicion desde Telegram se conecta en el siguiente incremento; por ahora quedan guardadas como borradores en el sistema.)`;
}

const inputTokens = usage.promptTokenCount || 0;
const outputTokens = usage.candidatesTokenCount || 0;
// Precio promocional gemini-3.6-flash (docs/research/08_ai_text_providers_and_safety.md): $0.75 / $3.75 por millon de tokens
const estimatedCost = (inputTokens / 1000000) * 0.75 + (outputTokens / 1000000) * 3.75;

return [{
  json: {
    chat_id: decision.chat_id,
    reply_text: replyText,
    conversation_id: decision.conversation_id,
    new_state: decision.new_state,
    new_flow: decision.new_flow,
    company_id: decision.company_id,
    content_type: decision.content_type,
    drafts_json: JSON.stringify(drafts),
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    estimated_cost: estimatedCost,
  },
}];
